import { formatNumber, roundTo } from "../src/codec/numberFormat";
import { decodeProfile, encodeProfile } from "../src/codec/settingsCodec";
import { eq, run, test, truthy } from "./harness";

test("profiles survive the storage encoding, including non-finite numbers", () => {
  const p = {
    deviceId: "d-1",
    name: "pump",
    firmware: "2.4.1",
    settings: { gain: 1.25, ceiling: Number.POSITIVE_INFINITY, floor: Number.NEGATIVE_INFINITY, bias: Number.NaN, tags: ["a", "b"] },
  };
  const back = decodeProfile(encodeProfile(p));
  eq(back.settings.gain, 1.25, "gain");
  eq(back.settings.ceiling === Number.POSITIVE_INFINITY, true, "ceiling");
  eq(back.settings.floor === Number.NEGATIVE_INFINITY, true, "floor");
  truthy(Number.isNaN(back.settings.bias as number), "bias should stay NaN");
  eq(back.settings.tags, ["a", "b"], "tags");
});

test("rounding is stable and leaves non-finite values alone", () => {
  eq(roundTo(0.1 + 0.2, 6), 0.3, "0.1+0.2");
  eq(roundTo(roundTo(2.0000004, 6), 6), 2, "idempotent");
  eq(roundTo(-0.0000001, 6), 0, "no negative zero");
  truthy(Number.isNaN(roundTo(Number.NaN, 6)), "NaN stays NaN");
  eq(roundTo(Number.POSITIVE_INFINITY, 6), Number.POSITIVE_INFINITY, "inf");
});

test("display formatting", () => {
  eq([formatNumber(Number.NaN), formatNumber(Number.POSITIVE_INFINITY), formatNumber(1.5)], ["n/a", "∞", "1.5"], "fmt");
});

run();
import { createApp } from "../src/app";
import { StepClock, eq, run, test } from "./harness";

function sensorProfile(offset: number) {
  return {
    deviceId: "boiler-7",
    name: "Boiler 7",
    firmware: "3.2.0",
    settings: {
      targetTemp: 72.5,
      maxPressure: 3.1,
      sensors: [
        { id: "t-in", offset: 0.15, gain: 1.02 },
        { id: "t-out", offset, gain: 0.98 },
      ],
      mode: "eco",
      uptimeSec: 100,
    },
  };
}

test("repeated heartbeats with an unchanged configuration add no history", () => {
  const app = createApp(new StepClock());
  eq(app.handle("POST", "/devices/boiler-7/report", sensorProfile(0.4)).status, 201, "first report");
  for (let i = 0; i < 3; i++) {
    const p = sensorProfile(0.4);
    p.settings.uptimeSec += i * 60;
    eq(app.handle("POST", "/devices/boiler-7/report", p).body, { rev: 1, changed: false }, `heartbeat ${i}`);
  }
});

test("a device whose sensor could not be calibrated stops growing history after its first report", () => {
  const app = createApp(new StepClock());
  for (let i = 0; i < 4; i++) app.handle("POST", "/devices/boiler-7/report", sensorProfile(Number.NaN));
  const h = app.handle("GET", "/devices/boiler-7/revisions").body as { count: number };
  eq(h.count, 1, "revision count");
});

test("status page reports in sync when the device runs exactly what was requested", () => {
  const app = createApp(new StepClock());
  app.handle("PUT", "/devices/boiler-7/desired", sensorProfile(Number.NaN));
  app.handle("POST", "/devices/boiler-7/report", sensorProfile(Number.NaN));
  const s = app.handle("GET", "/devices/boiler-7/status").body as { state: string; drift: string[] };
  eq([s.state, s.drift], ["in-sync", []], "status");
});

run();
declare const process: { exitCode?: number };

type Fn = () => void | Promise<void>;
const registered: [string, Fn][] = [];

export function test(name: string, fn: Fn): void {
  registered.push([name, fn]);
}

export function eq(actual: unknown, expected: unknown, label: string): void {
  const a = JSON.stringify(actual);
  const e = JSON.stringify(expected);
  if (a !== e) throw new Error(`${label}: expected ${e}, got ${a}`);
}

export function truthy(cond: boolean, label: string): void {
  if (!cond) throw new Error(label);
}

export async function run(): Promise<void> {
  let failed = 0;
  for (const [name, fn] of registered) {
    try {
      await fn();
      console.log(`ok   - ${name}`);
    } catch (e) {
      failed++;
      console.log(`FAIL - ${name}: ${e instanceof Error ? e.message : String(e)}`);
    }
  }
  console.log(failed === 0 ? "all passed" : `${failed} failed`);
  process.exitCode = failed === 0 ? 0 : 1;
}

export class StepClock {
  constructor(public t = 1_750_000_000_000) {}
  now(): number { return (this.t += 1000); }
}
import { RevisionStore } from "../src/store/revisionStore";
import { changedKeys } from "../src/util/diff";
import { eq, run, test } from "./harness";

const profile = (deviceId: string, gain: number) => ({ deviceId, name: "n", firmware: "1.0.0", settings: { gain } });

test("revisions are numbered per device and listed newest first", () => {
  const store = new RevisionStore();
  store.append("a", profile("a", 1), "report", 10, ["gain"]);
  store.append("b", profile("b", 1), "report", 11, ["gain"]);
  store.append("a", profile("a", 2), "import", 12, ["gain"]);
  eq(store.latest("a")?.rev, 2, "latest a");
  eq(store.latest("b")?.rev, 1, "latest b");
  eq(store.history("a", 10).map((r) => [r.rev, r.source]), [[2, "import"], [1, "report"]], "history");
  eq(store.history("a", 1).length, 1, "limit");
});

test("changed keys cover added, removed and modified settings", () => {
  eq(changedKeys({ a: 1, b: [1, 2], c: "x" }, { a: 1, b: [1, 3], d: true }), ["b", "c", "d"], "diff");
  eq(changedKeys({ a: { x: 1, y: 2 } }, { a: { y: 2, x: 1 } }), [], "key order does not matter");
  eq(changedKeys({ uptimeSec: 1 }, { uptimeSec: 2 }, ["uptimeSec"]), [], "ignored");
});

run();
import { compareVersions, needsUpgrade, newest } from "../src/util/semver";
import { eq, run, test } from "./harness";

test("versions compare numerically, not as text", () => {
  eq(compareVersions("1.10.0", "1.9.9") > 0, true, "minor 10 > 9");
  eq(compareVersions("2.0.0", "2.0.0"), 0, "equal");
  eq(needsUpgrade("3.1.9", "3.2.0"), true, "below minimum");
  eq(needsUpgrade("3.2.0", "3.2.0"), false, "at minimum");
});

test("newest skips malformed entries", () => {
  eq(newest(["1.2.3", "beta", "1.10.0", "1.9.0"]), "1.10.0", "newest");
  eq(newest([]), undefined, "empty");
});

run();

